class Zaehler:
    _i = None
    def __new__(cls):
        if cls._i is None:
            cls._i = super().__new__(cls)
            cls._i.n = 0
        return cls._i
    def plus(self):
        self.n += 1

Zaehler().plus()
Zaehler().plus()
print(Zaehler().n)

